                                                    </td>
                                                </tr>
                                                <tr class="TableStyle-StandardTable-Body-Body1">
                                                    <td class="TableStyle-StandardTable-BodyE-Column1-Body1">
                                                        <p><a href="get-accountname.html">Get(AccountName)</a></p>
                                                    </td>
                                                    <td class="TableStyle-StandardTable-BodyD-Column1-Body1">
                                                        <p>Returns the authenticated account name being used by the file''s current user.</p>
                                                    </td>
                                                </tr>
                                                <tr class="TableStyle-StandardTable-Body-Body1">
                                                    <td class="TableStyle-StandardTable-BodyE-Column1-Body1">
                                                        <p><a href="get-accountpassworddaysremaining.html">Get(AccountPasswordDaysRemaining)</a></p>
                                                    </td>
