                                                <tr class="TableStyle-StandardTable-Body-Body1">
                                                    <td class="TableStyle-StandardTable-BodyE-Column1-Body1">
                                                        <p><a href="get-accountprivilegesetname.html">Get(AccountPrivilegeSetName)</a></p>
                                                    </td>
                                                    <td class="TableStyle-StandardTable-BodyD-Column1-Body1">
                                                        <p>Returns the privilege set name being used by the account used to open the file.</p>
                                                    </td>
                                                </tr>
                                                <tr class="TableStyle-StandardTable-Body-Body1">
                                                    <td class="TableStyle-StandardTable-BodyE-Column1-Body1">
                                                        <p><a href="get-accounttype.html">Get(AccountType)</a></p>
                                                    </td>
