                                                <tr class="TableStyle-StandardTable-Body-Body1">
                                                    <td class="TableStyle-StandardTable-BodyE-Column1-Body1">
                                                        <p><a href="get-activefieldtablename.html">Get(ActiveFieldTableName)</a></p>
                                                    </td>
                                                    <td class="TableStyle-StandardTable-BodyD-Column1-Body1">
                                                        <p>Returns the name of the table occurrence that contains the field that has the focus.</p>
